-- User
create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  legacy_id text unique,
  email text not null unique,
  full_name text,
  role text not null default 'user' check (role in ('user', 'admin')),
  created_date timestamptz not null default now(),
  updated_date timestamptz not null default now(),
  phone text,
  avatar text,
  city text,
  country text,
  user_type text default 'private',
  dealer_id text,
  gdpr_consent boolean default false,
  gdpr_consent_date timestamptz,
  terms_consent boolean default false,
  notify_email boolean default true,
  notify_new_cars boolean default true,
  notify_price_drop boolean default true,
  notify_messages boolean default true,
  preferred_language text default 'ru',
  two_factor_enabled boolean default false
);
comment on table public.profiles is 'Base44 entity User';
comment on column public.profiles.phone is 'Телефон';
comment on column public.profiles.avatar is 'URL аватара';
comment on column public.profiles.city is 'Город';
comment on column public.profiles.country is 'Страна';
comment on column public.profiles.user_type is 'enum: private|dealer — Тип пользователя';
comment on column public.profiles.dealer_id is 'ID дилера (если dealer)';
comment on column public.profiles.gdpr_consent is 'Согласие GDPR';
comment on column public.profiles.gdpr_consent_date is 'Дата согласия GDPR';
comment on column public.profiles.terms_consent is 'Согласие с условиями использования';
comment on column public.profiles.notify_email is 'Email уведомления';
comment on column public.profiles.notify_new_cars is 'Уведомления о новых авто';
comment on column public.profiles.notify_price_drop is 'Уведомления о снижении цен';
comment on column public.profiles.notify_messages is 'Уведомления о сообщениях';
comment on column public.profiles.preferred_language is 'enum: ru|en|lv|lt|et — Предпочитаемый язык';
comment on column public.profiles.two_factor_enabled is 'Двухфакторная авторизация';
create trigger profiles_touch before update on public.profiles for each row execute function public.touch_updated_date();
create index profiles_created_date_idx on public.profiles (created_date desc);
create index profiles_dealer_id_idx on public.profiles (dealer_id);
create index profiles_country_idx on public.profiles (country);

-- ViewHistory
create table public.view_history (
  id text primary key default gen_random_uuid()::text,
  created_date timestamptz not null default now(),
  updated_date timestamptz not null default now(),
  created_by text,
  created_by_id uuid references auth.users(id) on delete set null,
  user_email text,
  car_id text,
  viewed_at timestamptz,
  description text
);
comment on table public.view_history is 'Base44 entity ViewHistory';
comment on column public.view_history.user_email is 'Email пользователя';
comment on column public.view_history.car_id is 'ID автомобиля';
comment on column public.view_history.viewed_at is 'Дата просмотра';
comment on column public.view_history.description is 'Дополнительное описание записи истории';
create trigger view_history_touch before update on public.view_history for each row execute function public.touch_updated_date();
create index view_history_created_date_idx on public.view_history (created_date desc);
create index view_history_car_id_idx on public.view_history (car_id);
create index view_history_user_email_idx on public.view_history (user_email);
